  reviewingAdmin ecommerce_admins? @relation(fields: [reviewed_by_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([requester_customer_id])
  @@index([requester_seller_id])
  @@index([status])
  // spellchecker: ignore-next-line
  @@index([requester_type, requester_customer_id], map: "ecommerce_admin_requests_requester_type_requester_cust_dc8dfd4e")
  @@index([requester_type, requester_seller_id])
  @@index([reviewed_by_id])
