  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  cartItems        ecommerce_cart_items[]
  inventoryRecords ecommerce_inventory_records[]
  orderItems       ecommerce_order_items[]

  //----
  // INDEXES
  //----
  @@unique([product_id, sku_code])
  @@index([product_id, deleted_at])
}

/// Multiple images per product with display ordering and thumbnail selection.
