export async function test_api_customer_profile_update_both_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const initialAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  typia.assert(initialAuth);
  // Store initial values for comparison
  const initialDisplayName = initialAuth.display_name;
  const initialPhoneNumber = initialAuth.phone_number;
  const initialUpdatedAt = initialAuth.updated_at;
  // 2. Update profile with both fields
  const newDisplayName = RandomGenerator.name();
  const newPhoneNumber = RandomGenerator.mobile();
  const updated = await api.functional.ecommerce.customer.profile.update(
    customerConnection,
    {
      body: {
        display_name: newDisplayName,
        phone_number: newPhoneNumber,
      } satisfies IEcommerceCustomer.IUpdate,
    },
  );
  typia.assert(updated);
  // 3. Validate response contains updated values
  TestValidator.equals(
    "display_name updated",
    updated.display_name,
    newDisplayName,
  );
  TestValidator.equals(
    "phone_number updated",
    updated.phone_number,
    newPhoneNumber,
  );
  // 4. Verify values changed from initial
  TestValidator.notEquals(
    "display_name changed",
    updated.display_name,
    initialDisplayName,
  );
  TestValidator.notEquals(
    "phone_number changed",
    updated.phone_number,
    initialPhoneNumber,
  );
  // 5. Verify timestamp was updated
  TestValidator.predicate(
    "updated_at is valid date-time",
    () => !isNaN(Date.parse(updated.updated_at)),
  );
  TestValidator.predicate(
    "updated_at reflects change",
    () => updated.updated_at >= initialUpdatedAt,
  );
  // 6. Verify account is still active
  TestValidator.equals("account not deleted", updated.deleted_at, null);
}

