        ),
      );
    }
  });
  // 7. Validate no password hashes exposed in responses
  TestValidator.predicate(
    "no password_hash field in responses",
    allAdmins.data.every(
      (admin) => !("password_hash" in admin) && !("password" in admin),
    ),
  );
}

