  );
  // 10. Test status filter with "deleted" status
  const deletedList: IPageIEcommerceAdmin.ISummary =
    await api.functional.ecommerce.admin.admins.index(adminConnection, {
      body: {
        status: "deleted",
        limit: 100,
        page: 1,
