/**
 * Test successful cart item quantity update workflow.
 *
 * Validates the complete cart item quantity update flow including customer authentication, seller product setup, initial cart item creation, and quantity modification. Ensures that the cart item correctly updates the quantity field and maintains stock availability status.
 *
 * Special attention is given to verifying that the updated_at timestamp changes and the quantity reflects the new value after the update operation.
 *
 * 1. Customer registers with email and credentials.
 * 2. Seller registers, authenticates, and creates a product with a variant.
 * 3. Customer adds the variant to their cart with initial quantity.
 * 4. Customer updates the cart item quantity to a new positive value.
 * 5. Validates the updated cart item has the new quantity and updated_at timestamp changed.
 */
export async function test_api_cart_item_quantity_update_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  typia.assert(customer);
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceSeller.IJoin,
  });
  typia.assert(seller);
  // 3. Seller creates a product
  const product = await api.functional.ecommerce.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
        variants: [
          {
            sku_code: RandomGenerator.alphabets(8).toUpperCase(),
            option_values: `color=${RandomGenerator.alphabets(5)};size=${RandomGenerator.alphabets(5)}`,
            price: typia.random<
              number & tags.Type<"uint32"> & tags.Minimum<1000>
            >(),
          },
        ],
      } satisfies IEcommerceProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Get the variant from the product
  const variant = product.variants[0];
  typia.assert(variant);
  // 5. Customer adds variant to cart with initial quantity
  const initialQuantity = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
  >();
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const cartItem = await api.functional.ecommerce.customer.carts.items.create(
    customerConnection,
    {
      cartId,
      body: {
        ecommerce_product_variant_id: variant.id,
        quantity: initialQuantity,
      } satisfies IEcommerceCartItem.ICreate,
    },
  );
  typia.assert(cartItem);
  // Store initial updatedAt for comparison (IEcommerceCartItem uses camelCase)
  const initialUpdatedAt = cartItem.updatedAt;
  // 6. Update cart item quantity to a different value
  const newQuantity =
    initialQuantity === 1
      ? (2 satisfies number & tags.Type<"int32"> & tags.Minimum<0>)
      : (1 satisfies number & tags.Type<"int32"> & tags.Minimum<0>);
  const updatedCartItem =
    await api.functional.ecommerce.customer.carts.items.patchByCartid(
      customerConnection,
      {
        cartId,
        body: {
          quantity: newQuantity satisfies
            | (number & tags.Type<"int32"> & tags.Minimum<0>)
            | undefined,
        } satisfies IEcommerceCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItem);
  // 7. Validate the update
  // IEcommerceCartItem.ISummary uses snake_case
  TestValidator.equals(
    "quantity updated",
    updatedCartItem.quantity,
    newQuantity,
  );
  TestValidator.notEquals(
    "updated_at changed",
    updatedCartItem.updated_at,
    initialUpdatedAt,
  );
  TestValidator.predicate(
    "variant matches",
    updatedCartItem.productVariant.id === variant.id,
  );
}

