  );
  TestValidator.predicate(
    "wishlist item not soft-deleted",
    retrievedItem.deleted_at === null,
  );
  TestValidator.predicate(
    "wishlist belongs to customer",
    retrievedItem.ecommerceWishlist.customer.id === customerAuth.id,
  );
