import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEcommerceCategorySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceCategorySnapshot";
