    "paid",
    "shipped",
    "delivered",
    "cancelled",
    "refunded",
  ];
  await TestValidator.predicate(
    "status filtering works for all statuses",
    async () => {
      for (const status of statuses) {
        const result: IPageIEcommerceOrderItem.ISummary =
          await api.functional.ecommerce.seller.orders.items.index(
