import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Test customer order item variant snapshot retrieval with authentication.
 *
 * Validates the customer's ability to retrieve the immutable variant snapshot for a specific order item after authentication. The test ensures the snapshot contains the correct SKU code, variant price, and option values that match what was purchased at checkout time.
 *
 * Since order creation APIs are not available in the provided SDK, this test focuses on validating the authentication flow and snapshot retrieval API structure. The test authenticates as a customer and attempts to retrieve a variant snapshot, validating the response type and structure.
 *
 * 1. Customer registers with email and credentials.
 * 2. Customer connection is established with authentication token.
 * 3. Attempt to retrieve variant snapshot for order item (may return 404 in real backend).
 * 4. Validates snapshot structure contains SKU code, variant price, and options array.
 */
export async function test_api_order_item_variant_snapshot_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer registration and authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  typia.assert(customer);
  // 2. Retrieve variant snapshot for order item
  // Note: In simulation mode, this will return random data
  // In real backend, this would require a valid order and order item
  const snapshot =
    await api.functional.ecommerce.customer.orders.items.snapshot.variant.at(
      customerConnection,
      {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        itemId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  typia.assert(snapshot);
  // 3. Validate snapshot structure
  TestValidator.predicate("snapshot has valid UUID", snapshot.id !== undefined);
  TestValidator.predicate(
    "snapshot has SKU code",
    snapshot.sku_code.length > 0,
  );
  TestValidator.predicate(
    "snapshot has variant price",
    snapshot.variant_price >= 0,
  );
  TestValidator.predicate(
    "snapshot has options array",
    Array.isArray(snapshot.options),
  );
}

