import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

export async function test_api_order_item_variant_snapshot_access_control(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register Customer A (potential order owner)
  const customerAConnection: api.IConnection = { host: connection.host };
  const customerA = await authorize_customer_join(customerAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  typia.assert(customerA);
  // 2. Register Customer B (unauthorized user attempting to access another's order)
  const customerBConnection: api.IConnection = { host: connection.host };
  const customerB = await authorize_customer_join(customerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  typia.assert(customerB);
  // 3. Generate random order and item IDs (representing Customer A's order)
  const randomOrderId = typia.random<string & tags.Format<"uuid">>();
  const randomItemId = typia.random<string & tags.Format<"uuid">>();
  // 4. Customer B attempts to access order item variant snapshot for an order they don't own
  // The system should reject this with 403 Forbidden
  await TestValidator.httpError(
    "Customer B should get 403 when accessing order item variant snapshot they don't own",
    403,
    async () => {
      await api.functional.ecommerce.customer.orders.items.snapshot.variant.at(
        customerBConnection,
        {
          orderId: randomOrderId,
          itemId: randomItemId,
        },
      );
    },
  );
  // 5. Also verify Customer A cannot access non-existent order (should get 404 or 403)
  await TestValidator.httpError(
    "Customer A should get error when accessing non-existent order item variant snapshot",
    [403, 404],
    async () => {
      await api.functional.ecommerce.customer.orders.items.snapshot.variant.at(
        customerAConnection,
        {
          orderId: randomOrderId,
          itemId: randomItemId,
        },
      );
    },
  );
}

