      await api.functional.ecommerce.customer.orders.items.refund_requests.create(
        customerConnection,
        {
          orderId,
          itemId,
          body: {
            reason: RandomGenerator.paragraph({ sentences: 2 }),
          } satisfies IEcommerceRefundRequest.ICreate,
        },
      );
    },
  );
}

