        adminId: admin.id,
        body: {
          grade: "regular",
        } satisfies IEcommerceAdministratorGrade.IUpdate,
      });
    },
  );
  // 5. Verify admin's grade in auth response still shows 'super'
  TestValidator.equals(
    "admin grade in auth response is super",
    admin.grade.grade,
