import { EcommerceCategoryAtSummaryTransformer } from "./EcommerceCategoryAtSummaryTransformer";

export namespace EcommerceCategoryTransformer {
  export type Payload = Prisma.ecommerce_categoriesGetPayload<
    ReturnType<typeof select>
  >;
  export function select() {
    return {
      select: {
        id: true,
        name: true,
        description: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        parentCategory: EcommerceCategoryAtSummaryTransformer.select(),
        subcategories: EcommerceCategoryAtSummaryTransformer.select(),
        snapshots: {
          select: {
            id: true,
            created_at: true,
          },
        } satisfies Prisma.ecommerce_category_snapshotsFindManyArgs,
        products: {
          select: {
            id: true,
            name: true,
          },
        } satisfies Prisma.ecommerce_productsFindManyArgs,
      },
    } satisfies Prisma.ecommerce_categoriesFindManyArgs;
  }
  export async function transform(input: Payload): Promise<IEcommerceCategory> {
    return {
      id: input.id,
      name: input.name,
      description: input.description,
      parent: input.parentCategory
        ? await EcommerceCategoryAtSummaryTransformer.transform(
            input.parentCategory,
          )
        : null,
      subcategories: await ArrayUtil.asyncMap(
        input.subcategories,
        async (elem) =>
          await EcommerceCategoryAtSummaryTransformer.transform(elem),
      ),
      created_at: toISOStringSafe(input.created_at),
      updated_at: toISOStringSafe(input.updated_at),
      deleted_at: input.deleted_at ? toISOStringSafe(input.deleted_at) : null,
    } satisfies IEcommerceCategory;
  }
}

