export async function patchEcommerceCustomerOrdersOrderIdItems(props: {
  customer: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "customer";
  };
  orderId: string & tags.Format<"uuid">;
  body: IEcommerceOrderItem.IRequest;
}): Promise<IPageIEcommerceOrderItem.ISummary> {
  // Verify order exists and belongs to the customer
  await MyGlobal.prisma.ecommerce_orders.findUniqueOrThrow({
    where: {
      id: props.orderId,
      ecommerce_customer_id: props.customer.id,
    },
  });
  // Build where clause
  const whereInput: Prisma.ecommerce_order_itemsWhereInput = {
    ecommerce_order_id: props.orderId,
    deleted_at: null,
    ...(props.body.status !== undefined && {
      status: props.body.status,
    }),
    ...(props.body.sellerId !== undefined && {
      ecommerce_seller_id: props.body.sellerId,
    }),
    ...(props.body.dateFrom !== undefined && {
      created_at: {
        gte: props.body.dateFrom,
      },
    }),
    ...(props.body.dateTo !== undefined && {
      created_at: {
        ...(props.body.dateFrom !== undefined
          ? { gte: props.body.dateFrom }
          : {}),
        lte: props.body.dateTo,
      },
    }),
  } satisfies Prisma.ecommerce_order_itemsWhereInput;
  // Build orderBy clause
  const sortBy = props.body.sortBy ?? "created_at";
  const sortOrder = props.body.sortOrder ?? "desc";
  const finalOrderBy = (
    sortBy === "status"
      ? { status: sortOrder as Prisma.SortOrder }
      : sortBy === "quantity"
        ? { quantity: sortOrder as Prisma.SortOrder }
        : sortBy === "unit_price"
          ? { unit_price: sortOrder as Prisma.SortOrder }
          : { created_at: sortOrder as Prisma.SortOrder }
  ) satisfies Prisma.ecommerce_order_itemsOrderByWithRelationInput;
  // Handle pagination
  const limit = Math.min(Math.max(props.body.limit ?? 20, 1), 100);
  const skip = props.body.cursor !== undefined ? 1 : 0;
  // Decode cursor if provided
  let cursor:
    | {
        created_at: string & tags.Format<"date-time">;
        id: string & tags.Format<"uuid">;
      }
    | undefined;
  if (props.body.cursor !== undefined) {
    try {
      const decoded = JSON.parse(
        Buffer.from(props.body.cursor, "base64").toString(),
      );
      cursor = {
        created_at: decoded.created_at,
        id: decoded.id,
      };
    } catch {
      cursor = undefined;
    }
  }
  // Query order items using transformer's select to match expected type
  const records = await MyGlobal.prisma.ecommerce_order_items.findMany({
    ...EcommerceOrderItemAtSummaryTransformer.select(),
    where: whereInput,
    orderBy: finalOrderBy,
    skip,
    ...(cursor !== undefined ? { cursor } : {}),
    take: limit,
  });
  // Count total records
  const total = await MyGlobal.prisma.ecommerce_order_items.count({
    where: whereInput,
  });
  // Transform results
  const data = await ArrayUtil.asyncMap(
    records,
    EcommerceOrderItemAtSummaryTransformer.transform,
  );
  // Return paginated response
  return {
    pagination: {
      current: 1,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data,
  } satisfies IPageIEcommerceOrderItem.ISummary;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceCustomer";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceAuthCustomerJoin(props: {
  ip: string;
  body: IEcommerceCustomer.IJoin;
}): Promise<IEcommerceCustomer.IAuthorized> {
  // 1. Check duplicate email
  const existing = await MyGlobal.prisma.ecommerce_customers.findFirst({
    where: { email: props.body.email, deleted_at: null },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }
  // 2. Hash password
  const passwordHash = await PasswordUtil.hash(props.body.password);
  // 3. Prepare timestamps
  const now = new Date();
  const createdAt: string & tags.Format<"date-time"> = toISOStringSafe(now);
  const updatedAt: string & tags.Format<"date-time"> = createdAt;
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const verificationExpires = new Date(Date.now() + 24 * 60 * 60 * 1000);
  // 4. Generate UUIDs
  const customerId: string & tags.Format<"uuid"> = v4();
  const sessionId: string & tags.Format<"uuid"> = v4();
  const verificationTokenId: string & tags.Format<"uuid"> = v4();
  const verificationToken: string = v4();
  // 5. Create customer record
  const customer = await MyGlobal.prisma.ecommerce_customers.create({
    data: {
      id: customerId,
      email: props.body.email,
      password_hash: passwordHash,
      display_name: props.body.display_name,
      phone_number: props.body.phone_number ?? null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  // 6. Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  // 7. Create session with actual tokens
  await MyGlobal.prisma.ecommerce_customer_sessions.create({
    data: {
      id: sessionId,
      ecommerce_customer_id: customerId,
      access_token: token.access,
      refresh_token: token.refresh,
      ip: props.body.ip ?? props.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });
  // 8. Create email verification token
  await MyGlobal.prisma.ecommerce_customer_email_verifications.create({
    data: {
      id: verificationTokenId,
      ecommerce_customer_id: customerId,
      token: verificationToken,
      expires_at: verificationExpires,
      verified_at: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  // 9. Return IAuthorized
  return {
    id: customerId,
    display_name: customer.display_name,
    phone_number: customer.phone_number ?? null,
    created_at: createdAt,
    updated_at: updatedAt,
    deleted_at: null,
    token,
  } satisfies IEcommerceCustomer.IAuthorized;
}

