    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: pages,
    } satisfies IPage.IPagination,
    data: await EcommerceCategoryAtSummaryTransformer.transformAll(records),
  } satisfies IPageIEcommerceCategory.ISummary;
}

