import { postEcommerceAuthAdminRefresh } from "../../../../providers/postEcommerceAuthAdminRefresh";

@Controller("/ecommerce/auth/admin")
export class EcommerceAuthAdminController {
  /**
   * Submit administrator registration request with email, password, and reason for approval.
   *
   * This endpoint allows users to request administrator access by providing their email address, password, and justification. The system validates the credentials against security requirements and creates a pending administrator request that requires super admin approval before full access is granted.
   *
   * **Request Validation**
   * - Email must be unique across all admin accounts
   * - Password must meet minimum strength requirements (8+ characters, mixed case, numbers)
   * - Reason field is required and must be non-empty
   *
   * **Response**
   * Returns IAuthorized with temporary access and refresh tokens. The admin account remains in pending approval status until a super admin reviews and approves the request via the admin_requests approval endpoint.
   *
   * **Related Operations**
   * - login: After approval, use login endpoint with same credentials
   * - refresh: Renew expired tokens using refresh token
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator registration request with email, password, and approval reason.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Administrator registration endpoint. Validates email uniqueness and password strength, creates administrator request record in ecommerce_admin_requests table, sends email verification token to ecommerce_admin_email_verifications table. Requires email format validation (RFC 5322), password minimum 8 characters with uppercase, lowercase, number. On success, returns IAuthorized with temporary tokens pending approval. Implementation: 1) Validate request body against schema, 2) Check email not already registered in ecommerce_admins, 3) Create admin request record with reason, 4) Generate and store email verification token with expiration, 5) Return IAuthorized with limited-scope tokens.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceAdmin.IJoin,
  ): Promise<IEcommerceAdmin.IAuthorized> {
    try {
      return await postEcommerceAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate administrator with email and password, returning JWT access and refresh tokens.
   *
   * This endpoint validates administrator credentials against the ecommerce_admins table and issues JWT tokens for subsequent authenticated requests. The administrator must have approved status to successfully log in.
   *
   * **Authentication Flow**
   * - Email and password are validated against stored credentials
   * - Administrator approval status must be 'approved' (pending requests cannot login)
   * - JWT access token expires in 15 minutes
   * - JWT refresh token expires in 7 days and is stored in ecommerce_admin_sessions
   *
   * **Token Usage**
   * Access tokens must be included in Authorization header as Bearer token for all authenticated admin endpoints. Refresh tokens are used with the refresh endpoint to obtain new access tokens without re-authentication.
   *
   * **Security Considerations**
   * - Failed login attempts are logged in ecommerce_admin_audit_logs
   * - Account lockout may apply after multiple failed attempts
   * - Sessions are invalidated on password change or admin grade change
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator login credentials with email and password.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Administrator login endpoint. Validates email/password against ecommerce_admins table, checks approval status (must be approved), generates JWT access and refresh tokens stored in ecommerce_admin_sessions table. Implementation: 1) Validate request body, 2) Find admin by email in ecommerce_admins, 3) Verify password hash match, 4) Check approval_status is 'approved', 5) Generate JWT access token (15min expiry) and refresh token (7day expiry), 6) Store session in ecommerce_admin_sessions with grade-based permissions, 7) Return IAuthorized with tokens and admin info including grade.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceAdmin.ILogin,
  ): Promise<IEcommerceAdmin.IAuthorized> {
    try {
      return await postEcommerceAuthAdminLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew expired access token using valid refresh token.
   *
   * This endpoint exchanges a valid refresh token for new access and refresh tokens without requiring re-authentication. It validates the refresh token against stored sessions and ensures the administrator's account status and grade remain unchanged.
   *
   * **Refresh Token Validation**
   * - Refresh token must be valid and not expired (7-day lifespan)
   * - Administrator account must still exist with approved status
   * - Administrator grade must not have changed since token issuance
   * - Session must not have been invalidated (password change, grade change, or manual revocation)
   *
   * **Token Rotation**
   * Each refresh operation issues a new refresh token (rotation policy). The old refresh token becomes invalid immediately after successful use to prevent replay attacks.
   *
   * **Session Management**
   * Refresh tokens are stored in ecommerce_admin_sessions table and linked to the administrator's current grade. If the admin's grade changes (promotion/demotion via grade_transitions), all existing sessions are invalidated.
   *
   * **Related Operations**
   * - login: Initial authentication to obtain first refresh token
   * - join: Administrator registration (requires approval before login)
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token request for token renewal.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Token refresh endpoint. Validates refresh token against ecommerce_admin_sessions table, checks expiration and validity, issues new access and refresh tokens. Implementation: 1) Validate refresh token from request body, 2) Find session in ecommerce_admin_sessions by refresh token, 3) Verify session not expired and admin still exists with approved status, 4) Check admin grade hasn't changed (invalidates old sessions), 5) Generate new JWT access token and refresh token, 6) Update session record with new refresh token, 7) Return IAuthorized with new tokens.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceAdmin.IRefresh,
  ): Promise<IEcommerceAdmin.IAuthorized> {
    try {
      return await postEcommerceAuthAdminRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
