import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IEcommerceWishlist } from "../../../../api/structures/IEcommerceWishlist";
import { IEcommerceWishlistItem } from "../../../../api/structures/IEcommerceWishlistItem";
import { IPageIEcommerceWishlistItem } from "../../../../api/structures/IPageIEcommerceWishlistItem";
import { CustomerAuth } from "../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../decorators/payload/CustomerPayload";
import { getEcommerceCustomerWishlistsWishlistId } from "../../../../providers/getEcommerceCustomerWishlistsWishlistId";
import { patchEcommerceCustomerWishlists } from "../../../../providers/patchEcommerceCustomerWishlists";

@Controller("/ecommerce/customer/wishlists")
export class EcommerceCustomerWishlistsController {
  /**
   * Retrieve a paginated list of products saved to the authenticated customer's wishlist.
   *
   * This endpoint returns wishlist items with associated product information, allowing customers to browse their saved products with filtering and pagination support. Each customer has exactly one personal wishlist that is automatically created upon account registration.
   *
   * **Access Control**
   *
   * Only the authenticated wishlist owner can access this endpoint. The system validates that the requesting customer matches the wishlist owner before returning any data. Administrators cannot view individual customer wishlists as this data is private.
   *
   * **Product Availability**
   *
   * Wishlist items referencing deleted products are automatically removed from the system. If a seller deletes a product, it is immediately removed from all customer wishlists to maintain data consistency.
   *
   * **Pagination**
   *
   * The response uses cursor-based pagination to efficiently handle large wishlists. Customers can navigate through pages to view all saved products.
   *
   * @param connection
   * @param body Search criteria for filtering wishlist items including product name search, date range filters, availability status, and pagination parameters.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the ecommerce_wishlist_items table for the authenticated customer's wishlist.
   *
   * **Implementation Steps**
   *
   * 1. Extract the authenticated customer ID from the session token
   * 2. Find the customer's wishlist by querying ecommerce_wishlists where ecommerce_customer_id matches the authenticated customer
   * 3. Join with ecommerce_products to include product details (name, price, images, availability status)
   * 4. Apply search filters from request body:
   *    - Filter by product name (case-insensitive partial match)
   *    - Filter by added date range (created_at)
   *    - Filter by product availability status
   * 5. Apply pagination parameters (cursor, limit)
   * 6. Sort results by created_at descending (newest items first)
   * 7. Return paginated summary with product information
   *
   * **Edge Cases**
   *
   * - Customer has no wishlist items: Return empty page with zero count
   * - Product was deleted: Item should not appear (handled by cascade delete on foreign key)
   * - Invalid pagination cursor: Return 400 Bad Request
   * - Customer not authenticated: Return 401 Unauthorized
   *
   * **Performance Considerations**
   *
   * - Use index on (ecommerce_wishlist_id, created_at) for efficient filtering and sorting
   * - Limit result set size to prevent excessive memory usage
   * - Include only necessary product fields in summary response
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceWishlistItem.IRequest,
  ): Promise<IPageIEcommerceWishlistItem.ISummary> {
    try {
      return await patchEcommerceCustomerWishlists({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a customer's wishlist with all saved products.
   *
   * This operation returns the complete wishlist entity including metadata and all wishlist items. Each item contains the product information that was saved. The system validates that the authenticated customer owns the requested wishlist before returning data.
   *
   * **Access Control**
   *
   * Only the customer who owns the wishlist can view it. Administrators cannot access individual customer wishlists as this data is private to each customer.
   *
   * **Automatic Cleanup**
   *
   * Wishlist items referencing deleted products are automatically removed from the system. If a seller deletes a product, it disappears from all customer wishlists immediately without notification.
   *
   * @param connection
   * @param wishlistId Unique identifier of the wishlist to retrieve (UUID format, global scope)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the ecommerce_wishlists table by id UUID. Validate that the authenticated customer's id matches the ecommerce_customer_id foreign key. If mismatch, return 403 Forbidden.
   *
   * Join with ecommerce_wishlist_items to fetch all active items (where deleted_at IS NULL). For each item, join with ecommerce_products to include product details.
   *
   * Apply soft delete filtering: only return wishlist items where deleted_at IS NULL.
   *
   * Return 404 Not Found if wishlist does not exist or has been soft-deleted (deleted_at IS NOT NULL).
   *
   * Return 403 Forbidden if authenticated customer does not own the requested wishlist.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":wishlistId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceWishlist> {
    try {
      return await getEcommerceCustomerWishlistsWishlistId({
        customer,
        wishlistId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
