import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IEcommerceOrder } from "../../../../api/structures/IEcommerceOrder";
import { IPageIEcommerceOrder } from "../../../../api/structures/IPageIEcommerceOrder";
import { CustomerAuth } from "../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../decorators/payload/CustomerPayload";
import { getEcommerceCustomerOrdersOrderId } from "../../../../providers/getEcommerceCustomerOrdersOrderId";
import { patchEcommerceCustomerOrders } from "../../../../providers/patchEcommerceCustomerOrders";

@Controller("/ecommerce/customer/orders")
export class EcommerceCustomerOrdersController {
  /**
   * Retrieves a paginated list of orders with filtering and sorting capabilities.
   *
   * This endpoint supports searching orders by status, order number, and date ranges. Results are sorted by creation date in descending order (newest first) as required by the order history pagination specification. Authentication is required, and customers can only view their own orders unless they have administrator privileges.
   *
   * **Pagination**: The endpoint supports offset-based pagination with page and limit parameters for handling large order histories. The response includes pagination metadata with total count and navigation information.
   *
   * **Security**: Row-level security is enforced based on the authenticated user's role. Regular customers see only their own orders filtered by ecommerce_customer_id, while administrators can view all orders on the platform for oversight purposes.
   *
   * **Filtering**: Supported filters include order status, order number search, and creation date ranges. All filters are optional and can be combined.
   *
   * @param connection
