    body: IEcommerceOrderItem.IForceCancel,
  ): Promise<IEcommerceOrderItem> {
    try {
      return await postEcommerceAdminOrdersOrderIdItemsItemIdForceCancel({
        admin,
        orderId,
        itemId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
